_GT = ''
# 21-30 GREENTE Halyk …4950: построчная сверка выписки 01.01.2025–25.10.2026 с 1С (РН ДенежныеСредстваБезналичные), только чтение.
import zlib, base64, collections, csv
ACC = globals().get('ACC', '4950'); SRC = globals().get('SRC_B64', None) or _GT
BK = []
for t in zlib.decompress(base64.b64decode(SRC)).decode().split():
    sg = '+' if '+' in t else '-'; k, v = t.split(sg)
    BK.append((datetime.date(2000 + int(k[:2]), int(k[2:4]), int(k[4:6])), int(v) * (1 if sg == '+' else -1), 'банк'))
C1 = []
for r in q('ВЫБРАТЬ Т.Регистратор КАК Р, Т.Период КАК П, Т.ВидДвижения КАК В_, Т.Сумма КАК С, Т.БанковскийСчет КАК Б ИЗ РегистрНакопления.ДенежныеСредстваБезналичные КАК Т ГДЕ Т.БанковскийСчет.НомерСчета ПОДОБНО &А И Т.Период МЕЖДУ &Н И &К', А='%' + ACC, Н=datetime.datetime(2025, 1, 1), К=datetime.datetime(2026, 10, 26, 4, 59)):
    p = r['П'] + datetime.timedelta(hours=5) if hasattr(r['П'], 'hour') else r['П']
    sg = 1 if 'Приход' in s(r['В_']) or s(r['В_']) == '0' else -1
    C1.append((datetime.date(p.year, p.month, p.day), round(float(r['С']) * 100) * sg, s(r['Р'])))
print('банк операций', len(BK), 'приход', f"{sum(x[1] for x in BK if x[1]>0)/100:,.2f}", 'расход', f"{-sum(x[1] for x in BK if x[1]<0)/100:,.2f}")
print('1С движений', len(C1), 'приход', f"{sum(x[1] for x in C1 if x[1]>0)/100:,.2f}", 'расход', f"{-sum(x[1] for x in C1 if x[1]<0)/100:,.2f}")
def match(A, B, win):
    idx = collections.defaultdict(list)
    for i, b in enumerate(B): idx[b[1]].append(i)
    used = set(); left = []
    for a in A:
        best = None
        for i in idx.get(a[1], []):
            if i in used: continue
            dd = abs((B[i][0] - a[0]).days)
            if dd <= win and (best is None or dd < best[0]): best = (dd, i)
        if best: used.add(best[1])
        else: left.append(a)
    return left, [b for i, b in enumerate(B) if i not in used]
LB, LC = match(BK, C1, 0); LB, LC = match(LB, LC, 5)
print('НЕТ В 1С:', len(LB), f"{sum(x[1] for x in LB)/100:,.2f}", '| НЕТ В БАНКЕ:', len(LC), f"{sum(x[1] for x in LC)/100:,.2f}")
M = collections.defaultdict(lambda: [0, 0, 0, 0])
for x in LB: M[x[0].strftime('%Y-%m')][0] += x[1]; M[x[0].strftime('%Y-%m')][1] += 1
for x in LC: M[x[0].strftime('%Y-%m')][2] += x[1]; M[x[0].strftime('%Y-%m')][3] += 1
for m in sorted(M): print(f"  {m} нет в 1С {M[m][1]:>3} {M[m][0]/100:>15,.2f} | нет в банке {M[m][3]:>3} {M[m][2]/100:>15,.2f}")
fn = r'D:\anescom_edo\data\reports\Сверка_банк_GREENTE_4950_2025-2026.csv'
with open(fn, 'w', encoding='utf-8-sig', newline='') as fh:
    w = csv.writer(fh, delimiter=';'); w.writerow(['Где нет', 'Дата', 'Сумма', 'Документ 1С'])
    for x in sorted(LB): w.writerow(['нет в 1С', x[0].strftime('%d.%m.%Y'), f"{x[1]/100:.2f}".replace('.', ','), ''])
    for x in sorted(LC): w.writerow(['нет в банке', x[0].strftime('%d.%m.%Y'), f"{x[1]/100:.2f}".replace('.', ','), x[2]])
print('CSV', fn)
for x in sorted(LC, key=lambda x: -abs(x[1]))[:12]: print('  1С>', x[0], f"{x[1]/100:,.2f}", x[2][:55])
for x in sorted(LB, key=lambda x: -abs(x[1]))[:12]: print('  БАНК>', x[0], f"{x[1]/100:,.2f}")
